package com.example.app;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class App {

    private static final Logger log = LoggerFactory.getLogger(App.class);

    public static void main(String[] args) {
        log.info("Application starting");

        Greeter greeter = new Greeter();
        log.debug("Greeting with a name: {}", args.length > 0 ? args[0] : "World");
        System.out.println(greeter.greet(args.length > 0 ? args[0] : "World"));

        log.info("Application finished");
    }
}

package com.example.app;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Greeter {

    private static final Logger log = LoggerFactory.getLogger(Greeter.class);

    public String greet(String name) {
        log.debug("Building greeting for '{}'", name);
        return "Hello, " + name + "!";
    }
}

package com.example.app;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class GreeterTest {

    @Test
    void greetsByName() {
        assertEquals("Hello, World!", new Greeter().greet("World"));
    }
}
